  const { name } = req.body;
  if (name === undefined || typeof name !== 'string') {
    return res.status(400).json({ error: 'Missing or invalid "name" field: must be a string.' });
  }

  const newUser = {
    id: users.length + 1,
    name,
    email: `${name.toLowerCase()}@example.com`,
  };
  users.push(newUser);
  res.status(201).json(newUser);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

